import {sortAlpha, sortWeight } from "../redux/actions/index";


function Filter1({ setCurrentPage }) {

    const handleSortAlpha = e => {
        sortAlpha(e.target.value);
      setCurrentPage(1);
    };
  
    const handleSortWeight = e => {
        sortWeight(e.target.value);
      setCurrentPage(1);
    };
  
    return (
      <div>
        <h3 >Ordenar por:</h3>
        <div >
          <div>
            <label>Alfabeto</label>
            <select  onChange={handleSortAlpha}>
              <option value="asc">Ascendente</option>
              <option value="desc">Descendente</option>
            </select>
          </div>
          <div>
            <label>Peso</label>
            <select  onChange={handleSortWeight}>
              <option value="asc">Ascendente</option>
              <option value="desc">Descendente</option>
            </select>
          </div>
        </div>
      </div>
    );
  }
  export default Filter1;
